// TASK-0039 — V1 Dynamic Filters, product acceptance in real WebView2. No
// simulated DOM, no alternate renderer, no personal data: both trees under test
// were generated by task0039-seed-proof.py and die with the proof root.
//
// One phase (the persistence of the filters across a restart is out of scope,
// P-19), on two REAL_ROOT brains:
//
//   1   baseline index
//   2   create a file and a folder (with a file in it) and modify a file, on
//       disk, outside the product process, then a real `Actualiser`
//   3   « Nouveaux » -> creations only
//   4   « Non vus » -> creations + the modification
//   5   type « fichiers » -> the folder stops being a match (it stays context)
//   6   availability local / en ligne seulement -> coherent on the real fixture
//   7   mark one element seen -> the count and the projection update
//   8   « Tout marquer vu » -> « Non vus » becomes empty
//   9   « Réinitialiser les filtres » -> the normal projection is back
//   10  more than 64 matches -> filtered pagination, nothing accumulated; an
//       Actualiser with a filter active re-reads the filter
//   11  a second brain -> no filter, no counter carried; and back
//   12  no absolute path / stable key / FileId / volume anywhere
//   13  no fatal console error
//
// Every filesystem change is made by THIS script directly on disk. Every UI
// action is a real mouse click or key event through CDP.
import assert from "node:assert/strict";
import { writeFile, mkdir } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
assert(/^task0039-[a-f0-9]+$/.test(variant));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, secondBrainId, absolutePath, secondAbsolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // real absolute paths, used only by THIS script's own fs calls — never sent into the page.
const secondRoot = secondAbsolutePath;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const exposedPayloads = [];
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
/** A REAL mouse click at the centre of the element (radios and checkboxes need one). */
async function click(selector) {
  const box = await evaluate(`(() => {
    const e = document.querySelector(${JSON.stringify(selector)});
    if (!e) return null;
    e.scrollIntoView({ block: "center" });
    const r = e.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2, disabled: !!e.disabled };
  })()`);
  assert(box, `click: selector not found — ${selector}`);
  assert(!box.disabled, `click: element is disabled — ${selector}`);
  await pause(80);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: box.x, y: box.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: box.x, y: box.y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: box.x, y: box.y, button: "left", clickCount: 1 });
  await pause(150);
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
function assertNoPathLeak(text, where) {
  for (const path of [root, secondRoot]) {
    const escaped = path.split("\\").join("\\\\");
    assert(!text.includes(path) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
}
async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
}

async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`!!document.querySelector('[data-testid="filter-panel"]')`);
  await until(`!!document.querySelector('[data-testid="change-journal"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
const revisionExpression = `(() => { const t = document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''; const m = /révision (\\d+)/.exec(t); return m ? Number(m[1]) : -1; })()`;
const currentRevision = () => evaluate(revisionExpression);
/** One real Actualiser click; resolves with the counters the UI shows for it. */
async function refreshAndSummarize() {
  const before = await currentRevision();
  await activate('[data-testid="lifecycle-refresh"]');
  await until(`${revisionExpression} > ${before}`);
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  await pause(600);
  const raw = await evaluate(
    `document.querySelector('[data-testid="change-summary"]')?.getAttribute('data-summary') ?? 'null'`,
  );
  const summary = JSON.parse(raw);
  assert(summary, "the report must show the change counters after Actualiser");
  return summary;
}
function assertCounters(summary, expected, where) {
  const actual = {
    created: summary.created,
    modified: summary.modified,
    renamed: summary.renamed,
    moved: summary.moved,
    deleted: summary.deleted,
    total: summary.total,
  };
  assert.deepEqual(actual, { created: 0, modified: 0, renamed: 0, moved: 0, deleted: 0, total: 0, ...expected }, where);
}
async function resolve(id, relativePath) {
  const reference = await invoke("map_resolve_node", { brainId: id, relativePath });
  assert(reference, `no node resolves at ${relativePath}`);
  return reference.nodeId;
}

// ---- the real filter panel ---------------------------------------------------
const setState = (state) => click(`[data-testid="filter-state-${state}"]`);
const toggleKind = (kind) => click(`[data-testid="filter-kind-${kind}"]`);
const setAvailability = (availability) => click(`[data-testid="filter-availability-${availability}"]`);
const filterActive = () => evaluate(`document.querySelector('[data-testid="filter-panel"]')?.getAttribute('data-active') === 'true'`);
const uiTotal = () =>
  evaluate(`(() => { const e = document.querySelector('[data-testid="filter-count"]'); return e ? Number(e.getAttribute('data-total')) : -1; })()`);
const waitTotal = (n, limit = 30000) =>
  until(`(() => { const e = document.querySelector('[data-testid="filter-count"]'); return !!e && Number(e.getAttribute('data-total')) === ${n}; })()`, limit);
/** What the panel lists: role, node id and the visible name of each row. */
const uiRows = () =>
  evaluate(`[...document.querySelectorAll('[data-testid="filter-result"]')].map((e) => ({
    nodeId: Number(e.getAttribute('data-node-id')),
    role: e.getAttribute('data-filter-role'),
    text: e.textContent.replace(/\\s+/g, ' ').trim(),
  }))`);
const rowsByRole = async (role) => (await uiRows()).filter((r) => r.role === role);
const uiPage = () => evaluate(`document.querySelector('[data-testid="filter-page"]')?.textContent ?? ''`);
const uiActiveText = () => evaluate(`document.querySelector('[data-testid="filter-active"]')?.textContent ?? ''`);
/** Cards actually drawn on the canvas, and their filter role. */
const drawnCards = () =>
  evaluate(`[...document.querySelectorAll('[data-card="true"]')].map((e) => ({
    nodeId: Number(e.getAttribute('data-node-id')),
    role: e.getAttribute('data-filter-role'),
    label: e.getAttribute('aria-label'),
  }))`);
const filterStateChecked = () =>
  evaluate(`(() => { const c = document.querySelector('[name="filter-state"]:checked'); return c ? c.value : null; })()`);
const kindsChecked = () =>
  evaluate(`[...document.querySelectorAll('[name="filter-kind"]:checked')].map((c) => c.value)`);
const availabilityChecked = () =>
  evaluate(`(() => { const c = document.querySelector('[name="filter-availability"]:checked'); return c ? c.value : null; })()`);
/** The backend's own answer — the reference the UI is compared with. */
async function apiFiltered(id, filter, after = null) {
  const view = await invoke("map_view", { brainId: id, after, filter });
  assert.equal(view.brainId, id, "a filtered page names the brain it was read from");
  assert(view.filtered, "a filtered page carries its filtered block");
  return view;
}
const pathsOf = async (view, ids) => {
  const byId = new Map(view.nodes.map((n) => [n.id, n.relativePath]));
  return ids.map((i) => byId.get(i)).sort();
};

async function openJournal() {
  const open = await evaluate(`document.querySelector('[data-testid="journal-toggle"]').getAttribute('aria-expanded') === 'true'`);
  if (!open) await activate('[data-testid="journal-toggle"]');
  await until(`!!document.querySelector('[data-testid="journal-total"]')`);
}
const waitUnseen = (n) =>
  until(`Number(document.querySelector('[data-testid="journal-unseen-total"]')?.getAttribute('data-unseen-total') ?? -1) === ${n}`);

const results = {};
try {
  await waitForAppReady();
} catch (error) {
  console.error(
    "DIAGNOSTIC app not ready:",
    JSON.stringify({
      body: (await evaluate("document.body?.innerText ?? ''")).slice(0, 600),
      fatal: fatal.map((e) => e.params?.exceptionDetails?.exception?.description ?? e.params?.entry?.text ?? e.method).slice(0, 5),
    }),
  );
  throw error;
}

// ---- 1 — baseline ---------------------------------------------------------------
const first = await refreshAndSummarize();
assert.equal(first.baselineEstablished, true, "a first build establishes the baseline");
assert.equal(await filterActive(), false, "no filter is active at the start");
assert.match(await uiActiveText(), /Aucun filtre actif/);
assert.equal(await uiTotal(), -1, "no counter without a filter");
results.filterPanelPresentInactiveAtStart = true;
const overview = await invoke("map_open", { brainId });
results.schemaVersion = overview.schemaVersion;
assert.equal(overview.schemaVersion, 6);

// ---- 2 — changes made on disk, outside the product -------------------------------
await mkdir(join(root, "nouveau-dossier"));
await writeFile(join(root, "nouveau-dossier", "neuf.txt"), "synthetique — objet cree\n", "utf8");
await writeFile(join(root, "x-neuf.txt"), "synthetique — un autre objet cree\n", "utf8");
await writeFile(join(root, "a-modifier.txt"), "synthetique — apres, plus long qu'avant\n", "utf8");
assertCounters(await refreshAndSummarize(), { created: 3, modified: 1, total: 4 }, "changes counters");
const dirId = await resolve(brainId, "nouveau-dossier");
const neufId = await resolve(brainId, "nouveau-dossier/neuf.txt");
const xId = await resolve(brainId, "x-neuf.txt");
const modId = await resolve(brainId, "a-modifier.txt");
const rootId = (await invoke("map_view", { brainId })).rootId;
assert.equal(await filterActive(), false, "an Actualiser without filter leaves the filter inactive");

// ---- 3 — Nouveaux: creations only --------------------------------------------------
await setState("NEW");
await waitTotal(3);
assert.equal(await filterActive(), true);
assert.match(await uiActiveText(), /Filtre actif — État : Nouveaux/, "the active filter is written in words");
let matches = await rowsByRole("match");
results.newShowsCreationsOnly =
  JSON.stringify(matches.map((r) => r.nodeId).sort((a, b) => a - b)) === JSON.stringify([dirId, neufId, xId].sort((a, b) => a - b)) &&
  !matches.some((r) => r.nodeId === modId);
assert(results.newShowsCreationsOnly, "« Nouveaux » lists the three creations and not the modification");
assert(matches.every((r) => /Correspondance/.test(r.text)), "a match is labelled « Correspondance » in words");
const contexts = await rowsByRole("context");
assert(contexts.length >= 1 && contexts.every((r) => /Contexte/.test(r.text) && !/Correspondance/.test(r.text)), "ancestors are labelled « Contexte »");
assert(contexts.some((r) => r.nodeId === rootId), "the root is shown as context, never as a match");
assert(!matches.some((r) => r.nodeId === rootId));
let api = await apiFiltered(brainId, { state: "NEW", kinds: [], availability: "ALL" });
assert.equal(api.filtered.filteredTotal, 3, "the backend agrees with the counter");
assert.equal(await uiTotal(), api.filtered.filteredTotal);
// The canvas draws the same roles, with the role in the accessible name.
let cards = await drawnCards();
assert(cards.find((c) => c.nodeId === neufId)?.role === "match" && /Correspondance/.test(cards.find((c) => c.nodeId === neufId).label));
assert(cards.find((c) => c.nodeId === rootId)?.role === "context" && /Contexte/.test(cards.find((c) => c.nodeId === rootId).label));
results.canvasDrawsRolesInWords = true;
// The modified file is not drawn at all: the view is built from the matches.
assert(!cards.some((c) => c.nodeId === modId), "the projection is the filtered page, not the normal view");

// ---- 4 — Non vus: creations + modification ----------------------------------------
await setState("UNSEEN");
await waitTotal(4);
matches = await rowsByRole("match");
results.unseenAddsTheModification =
  matches.length === 4 && matches.some((r) => r.nodeId === modId) && matches.some((r) => r.nodeId === neufId);
assert(results.unseenAddsTheModification, "« Non vus » adds the modified file");
assert.equal((await apiFiltered(brainId, { state: "UNSEEN", kinds: [], availability: "ALL" })).filtered.filteredTotal, 4);

// ---- 5 — combine with the type « fichiers » ---------------------------------------
await toggleKind("FILE");
await waitTotal(3);
matches = await rowsByRole("match");
const folderRow = (await uiRows()).find((r) => r.nodeId === dirId);
results.fileTypeExcludesFolders =
  matches.length === 3 && !matches.some((r) => r.nodeId === dirId) && folderRow?.role === "context" && /Contexte/.test(folderRow.text);
assert(results.fileTypeExcludesFolders, "« fichiers » drops the new folder from the matches; it stays visible as context");
assert.deepEqual(await kindsChecked(), ["FILE"]);
assert.match(await uiActiveText(), /État : Non vus · Type : fichiers/);
assert.equal((await apiFiltered(brainId, { state: "UNSEEN", kinds: ["FILE"], availability: "ALL" })).filtered.filteredTotal, 3);

// ---- 6 — availability ---------------------------------------------------------------
await setAvailability("LOCAL");
await waitTotal(3);
results.localIsCoherentOnTheRealFixture = (await uiTotal()) === 3;
await setAvailability("ONLINE_ONLY");
await waitTotal(0);
assert.equal((await rowsByRole("match")).length, 0, "no real local file is online-only");
assert.match(await uiActiveText(), /Disponibilité : en ligne seulement/);
const onlineApi = await apiFiltered(brainId, { state: "UNSEEN", kinds: ["FILE"], availability: "ONLINE_ONLY" });
assert.equal(onlineApi.filtered.filteredTotal, 0);
assert.equal(onlineApi.nodes.length, 1, "no match: only the root remains, as context");
results.onlineOnlyEmptyOnLocalFixture = true;
await setAvailability("LOCAL");
await waitTotal(3);
await setAvailability("ALL");
await waitTotal(3);

// ---- 7 — mark one element seen: count and projection follow -----------------------
await click(`[data-testid="filter-result"][data-node-id="${neufId}"]`);
await until(`!!document.querySelector('[data-testid="node-mark-seen"]')`);
assert.equal(await uiTotal(), 3, "selecting a result marks nothing");
await activate('[data-testid="node-mark-seen"]');
await waitTotal(2);
matches = await rowsByRole("match");
results.markSeenUpdatesCountAndProjection = matches.length === 2 && !matches.some((r) => r.nodeId === neufId);
assert(results.markSeenUpdatesCountAndProjection, "the marked element left the « Non vus » matches");
assert(!(await drawnCards()).some((c) => c.role === "match" && c.nodeId === neufId));
assert.equal((await apiFiltered(brainId, { state: "UNSEEN", kinds: ["FILE"], availability: "ALL" })).filtered.filteredTotal, 2);

// ---- 8 — « Tout marquer vu » -> « Non vus » is empty ------------------------------
await setState("UNSEEN");
await toggleKind("FILE"); // back to « Non vus » alone
await waitTotal(3);
await openJournal();
await activate('[data-testid="journal-mark-all"]');
await until(`!!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
assert.equal(await uiTotal(), 3, "the first click only opens the confirmation");
await activate('[data-testid="journal-mark-all-confirm-yes"]');
await waitUnseen(0);
await waitTotal(0);
results.markAllEmptiesUnseen = (await rowsByRole("match")).length === 0;
assert(results.markAllEmptiesUnseen);
assert.equal((await apiFiltered(brainId, { state: "UNSEEN", kinds: [], availability: "ALL" })).filtered.filteredTotal, 0);
await setState("NEW");
await waitTotal(0);

// ---- 9 — remove the filters: the normal projection is back ---------------------------
await click('[data-testid="filter-reset"]');
await until(`document.querySelector('[data-testid="filter-panel"]').getAttribute('data-active') === 'false'`);
assert.equal(await filterStateChecked(), "ALL");
assert.deepEqual(await kindsChecked(), []);
assert.equal(await availabilityChecked(), "ALL");
assert.equal(await uiTotal(), -1, "no counter once the filters are gone");
await until(`document.querySelectorAll('[data-card="true"][data-filter-role]').length === 0 && document.querySelectorAll('[data-card="true"]').length > 0`);
const normal = await invoke("map_view", { brainId });
assert.equal(normal.filtered ?? null, null, "the normal projection carries no filtered block");
results.resetRestoresTheNormalProjection =
  (await drawnCards()).length === normal.materializedCount && (await filterActive()) === false;
assert(results.resetRestoresTheNormalProjection, "the normal, unfiltered projection is drawn again");

// ---- 10 — more than 64 matches: filtered pagination ----------------------------------
// A filter left active across a real Actualiser is re-read from the core.
await setState("NEW");
await waitTotal(0);
await mkdir(join(root, "lot"));
for (let i = 0; i < 150; i++) {
  await writeFile(join(root, "lot", `lot-${String(i).padStart(3, "0")}.txt`), `synthetique ${i}\n`, "utf8");
}
assertCounters(await refreshAndSummarize(), { created: 151, total: 151 }, "bulk counters");
await waitTotal(151, 60000);
results.actualiserKeepsAndRereadsTheFilter = (await filterActive()) === true && (await uiTotal()) === 151;
assert(results.actualiserKeepsAndRereadsTheFilter, "a filter survives an Actualiser and is re-read");

const seenMatches = [];
const pagesSeen = [];
for (let page = 1; page <= 20; page++) {
  const rows = await uiRows();
  const pageMatches = rows.filter((r) => r.role === "match").map((r) => r.nodeId);
  const cardCount = (await drawnCards()).length;
  assert(cardCount <= 64, `page ${page} draws ${cardCount} cards, over the ordinary target`);
  assert(pageMatches.length >= 1 && pageMatches.length <= 63, `page ${page} shows ${pageMatches.length} matches`);
  assert.match(await uiPage(), new RegExp(`Page ${page} `));
  // Nothing accumulates: this page's matches are new, and only this page's rows are listed.
  for (const m of pageMatches) assert(!seenMatches.includes(m), `match ${m} served twice`);
  seenMatches.push(...pageMatches);
  pagesSeen.push({ page, matches: pageMatches.length, cards: cardCount });
  const nextDisabled = await evaluate(`document.querySelector('[data-testid="filter-next"]').disabled`);
  if (nextDisabled) break;
  await click('[data-testid="filter-next"]');
  await until(`(document.querySelector('[data-testid="filter-page"]')?.textContent ?? '').startsWith('Page ${page + 1} ')`);
}
results.paginationAcrossPages = pagesSeen;
assert(pagesSeen.length >= 3, "151 matches need at least three pages of at most 63");
assert.equal(seenMatches.length, 151, "every match was served exactly once");
assert.equal(new Set(seenMatches).size, 151);
// « Page précédente » goes back and replaces the page again.
const beforeBack = (await rowsByRole("match")).map((r) => r.nodeId);
await click('[data-testid="filter-prev"]');
await until(`(document.querySelector('[data-testid="filter-page"]')?.textContent ?? '').startsWith('Page ${pagesSeen.length - 1} ')`);
const afterBack = (await rowsByRole("match")).map((r) => r.nodeId);
assert(afterBack.length > 0 && !afterBack.some((m) => beforeBack.includes(m)), "the previous page replaces the last one");
results.previousPageReplaces = true;
// The backend's own first page matches the UI's counter.
api = await apiFiltered(brainId, { state: "NEW", kinds: [], availability: "ALL" });
assert.equal(api.filtered.filteredTotal, 151);
assert(api.nodes.length <= 64 && api.filtered.filterNextCursor, "the backend page is bounded and has a next cursor");

// ---- 11 — a second brain: no filter, no counter carried ------------------------------
assert.equal(await filterActive(), true);
await activate('[data-testid="composition-add-trigger"]');
await until(`!!document.querySelector('[data-testid="composition-add-item-${secondBrainId}"]')`);
await activate(`[data-testid="composition-add-item-${secondBrainId}"]`);
await until(`!!document.querySelector('[data-testid="composition-chip-${secondBrainId}"]')`);
await activate(`[data-testid="composition-chip-${secondBrainId}"]`);
await until(`document.querySelector('[data-testid="composition-chip-${secondBrainId}"]')?.getAttribute('aria-current') === 'true'`);
await until(`document.querySelector('[data-testid="filter-panel"]').getAttribute('data-active') === 'false'`);
assert.equal(await uiTotal(), -1, "no counter carried to the second brain");
assert.equal(await filterStateChecked(), "ALL");
assert.deepEqual(await kindsChecked(), []);
assert.equal(await availabilityChecked(), "ALL");
assert.match(await uiActiveText(), /Aucun filtre actif/);
const secondFirst = await refreshAndSummarize();
assert.equal(secondFirst.baselineEstablished, true);
await writeFile(join(secondRoot, "b-nouveau.txt"), "synthetique b\n", "utf8");
assertCounters(await refreshAndSummarize(), { created: 1, total: 1 }, "second brain counters");
await setState("NEW");
await waitTotal(1);
const secondApi = await apiFiltered(secondBrainId, { state: "NEW", kinds: [], availability: "ALL" });
assert.equal(secondApi.filtered.filteredTotal, 1, "the second brain counts only its own creation");
const secondRows = await rowsByRole("match");
assert(
  secondRows.length === 1 && /b-nouveau\.txt/.test(secondRows[0].text) && !secondRows.some((r) => /neuf|lot-|nouveau-dossier/.test(r.text)),
  "nothing of the first brain is listed",
);
// The first brain kept none of its filter: back on it, the normal projection.
await activate(`[data-testid="composition-chip-${brainId}"]`);
await until(`document.querySelector('[data-testid="composition-chip-${brainId}"]')?.getAttribute('aria-current') === 'true'`);
await until(`document.querySelector('[data-testid="filter-panel"]').getAttribute('data-active') === 'false'`);
assert.equal(await uiTotal(), -1);
await until(`document.querySelectorAll('[data-card="true"][data-filter-role]').length === 0`);
results.brainSwitchCarriesNoFilterNorCounter = true;

// ---- 12 / 13 -----------------------------------------------------------------------------
await assertConfidential();
results.noAbsolutePathOrIdentityLeak = true;

await mkdir(proofRoot, { recursive: true });
await writeFile(join(proofRoot, "phase1.json"), JSON.stringify(results));
console.log(JSON.stringify({ ok: true }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, "phase1-fatal-count.json"), JSON.stringify(fatal.length));
ws.close();
